extends Node2D

signal impact(point: Vector2)
var clock := 0.0
var settings := ConfigFile.new()
var frames_cache := {}
var serial := 0
const SOURCES = {"hit": ["003", 11], "appear": ["023", 49], "fly": ["500", 13]}

func _ready():
	settings.load("res://delivery.cfg")
	if not OS.get_cmdline_user_args().has("--verification"):
		_demo()

func _demo():
	spawn_appear(Vector2(150, 290))
	await get_tree().create_timer(0.15).timeout
	cast(Vector2(130, 150), Vector2(480, 190))
	await get_tree().create_timer(0.30).timeout
	cast(Vector2(130, 260), Vector2(480, 190))

func _frames(kind: String) -> SpriteFrames:
	if frames_cache.has(kind):
		return frames_cache[kind]
	var spec = SOURCES[kind]
	var frames := SpriteFrames.new()
	frames.remove_animation("default")
	frames.add_animation(kind)
	frames.set_animation_speed(kind, float(settings.get_value(kind, "fps", 30.0)))
	frames.set_animation_loop(kind, false)
	for i in range(spec[1]):
		var path = "res://assets/frames/%s/%s_%02d.png" % [spec[0], spec[0], i]
		var img = Image.load_from_file(path)
		frames.add_frame(kind, ImageTexture.create_from_image(img))
	frames_cache[kind] = frames
	return frames

func _sprite(kind: String, point: Vector2) -> AnimatedSprite2D:
	serial += 1
	var sprite := AnimatedSprite2D.new()
	sprite.name = "%s_%03d" % [kind, serial]
	sprite.set_meta("kind", kind)
	sprite.sprite_frames = _frames(kind)
	sprite.centered = false
	sprite.offset = settings.get_value(kind, "offset", Vector2.ZERO)
	var mat := CanvasItemMaterial.new()
	mat.blend_mode = int(settings.get_value(kind, "blend", 0))
	sprite.material = mat
	add_child(sprite)
	sprite.global_position = point
	sprite.play(kind)
	return sprite

func spawn_hit(point: Vector2) -> AnimatedSprite2D:
	if not bool(settings.get_value("hit", "allow_overlap", true)):
		for child in get_children():
			if child is AnimatedSprite2D and child.get_meta("kind") == "hit":
				return child
	var sprite = _sprite("hit", point)
	if bool(settings.get_value("hit", "cleanup", true)):
		sprite.animation_finished.connect(sprite.queue_free)
	impact.emit(point) # Existing legacy visual callback
	return sprite

func spawn_appear(point: Vector2) -> AnimatedSprite2D:
	var sprite = _sprite("appear", point)
	sprite.set_frame_and_progress(int(settings.get_value("appear", "start_frame", 4)), 0.0)
	if bool(settings.get_value("appear", "cleanup", true)):
		sprite.animation_finished.connect(sprite.queue_free)
	return sprite

func cast(start: Vector2, target: Vector2) -> AnimatedSprite2D:
	var sprite = _sprite("fly", start)
	sprite.set_meta("start", start)
	sprite.set_meta("target", target)
	sprite.set_meta("born", clock)
	if bool(settings.get_value("fly", "orient", true)):
		sprite.rotation = (target - start).angle()
	return sprite

func _process(delta):
	clock += delta
	for child in get_children():
		if not child is AnimatedSprite2D or child.get_meta("kind") != "fly":
			continue
		var start: Vector2 = child.get_meta("start")
		var target: Vector2 = child.get_meta("target")
		var duration = float(settings.get_value("fly", "duration", 0.5))
		var progress = clampf((clock - float(child.get_meta("born"))) / duration, 0.0, 1.0)
		child.global_position = start.lerp(target, progress)
		if progress >= 1.0:
			impact.emit(target)
			spawn_hit(target)
			child.queue_free()

from pathlib import Path
import argparse,subprocess,csv
from PIL import Image,ImageDraw,ImageChops
from export_assets import godot_binary

def sample(project,out,godot=None):
    out=Path(out).resolve();out.mkdir(parents=True,exist_ok=True)
    cmd=[godot_binary(godot),'--headless','--fixed-fps','60','--path',str(Path(project).resolve()),'--script',str(Path(__file__).with_name('sample_effects.gd')),'--',str(out),'--verification']
    p=subprocess.run(cmd,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=120)
    (out/'engine.log').write_text(p.stdout+p.stderr,encoding='utf-8')
    if p.returncode or 'ERROR:' in p.stderr:raise RuntimeError(p.stdout+p.stderr)

def render(out):
    out=Path(out);groups={}
    with (out/'scene-frames.csv').open(encoding='utf-8',newline='') as f:
        for r in csv.DictReader(f):
            group=groups.setdefault(int(r['frame']),[])
            if r['node']:group.append(r)
    sheet=Image.new('RGB',(4*640,2*390),(20,30,40))
    sampled=[20,34,44,58]
    for row,(theme,bg,ink) in enumerate([('dark',(15,25,40,255),'#A7C4D1'),('light',(230,236,241,255),'#385465')]):
        frames=[]
        for frame in range(0,121,2):
            im=Image.new('RGBA',(640,360),bg);d=ImageDraw.Draw(im)
            for x in range(0,640,40):d.line((x,0,x,360),fill=(*bg[:3],255) if x==0 else ((27,42,57,255) if theme=='dark' else (217,225,231,255)))
            for y in range(0,360,40):d.line((0,y,640,y),fill=(27,42,57,255) if theme=='dark' else (217,225,231,255))
            for x,y,name in [(150,290,'APPEAR'),(480,190,'TARGET')]:
                d.line((x-8,y,x+8,y),fill=ink,width=1);d.line((x,y-8,x,y+8),fill=ink,width=1);d.text((x+10,y+8),name,fill=ink)
            for r in groups[frame]:
                if r.get('visible','true').lower()!='true':continue
                src=Image.open(out/r['texture']).convert('RGBA')
                channels=src.split()
                src=Image.merge('RGBA',[ch.point(lambda x,f=float(r.get(k,1)):max(0,min(255,round(x*f)))) for ch,k in zip(channels,['red','green','blue','alpha'])])
                a,b,c,e,tx,ty,ox,oy=[float(r[k]) for k in ['a','b','c','d','tx','ty','offset_x','offset_y']]
                det=a*e-b*c
                if abs(det)<1e-12:continue
                ia,ib,ic,ie=e/det,-b/det,-c/det,a/det
                coeff=(ia,ib,-ia*tx-ib*ty-ox,ic,ie,-ic*tx-ie*ty-oy)
                transformed=src.transform(im.size,Image.Transform.AFFINE,coeff,resample=Image.Resampling.BICUBIC)
                if int(r['blend'])==1:
                    rgb=ImageChops.multiply(transformed.convert('RGB'),Image.merge('RGB',[transformed.getchannel('A')]*3))
                    im=ImageChops.add(im.convert('RGB'),rgb).convert('RGBA')
                else:im=Image.alpha_composite(im,transformed)
            d=ImageDraw.Draw(im);d.text((14,12),f'KO66 | {theme} | {frame/60:.2f}s | engine frame {frame}',fill=ink)
            frames.append(im.convert('RGB'))
            if frame in sampled:
                col=sampled.index(frame);sheet.paste(im.convert('RGB'),(col*640,row*390));ImageDraw.Draw(sheet).text((col*640+15,row*390+367),f'{theme} / {frame/60:.3f}s',fill='#D7E9F1')
        frames[0].save(out/f'{theme}.gif',save_all=True,append_images=frames[1:],duration=[30,30,40]*20+[30],loop=0,disposal=2,optimize=False)
    sheet.save(out/'contact-sheet.png')

def main():
    p=argparse.ArgumentParser();p.add_argument('--project',required=True);p.add_argument('--output',required=True);p.add_argument('--godot');a=p.parse_args();sample(a.project,a.output,a.godot);render(a.output);print('Exported engine-state CPU composite previews to '+str(Path(a.output).resolve()))
if __name__=='__main__':main()

extends SceneTree
var events: Array = []
var capture_tick := 0

func _initialize(): call_deferred("run")

func sprites(parent: Node) -> Array:
	var found: Array = []
	for child in parent.get_children():
		if child is AnimatedSprite2D: found.append(child)
		found.append_array(sprites(child))
	return found

func effective_color(node: CanvasItem) -> Color:
	var color = node.self_modulate
	var ancestor: Node = node
	while ancestor is CanvasItem:
		color *= ancestor.modulate
		ancestor = ancestor.get_parent()
	return color

func run():
	var out = OS.get_cmdline_user_args()[0]
	DirAccess.make_dir_recursive_absolute(out.path_join("textures"))
	var stage = load("res://stage.tscn").instantiate()
	root.add_child(stage)
	await process_frame
	stage.impact.connect(func(point): events.append([str(float(capture_tick+1)/60.0),str(point.x),str(point.y)]))
	var f = FileAccess.open(out.path_join("scene-frames.csv"),FileAccess.WRITE)
	f.store_csv_line(PackedStringArray(["frame","time","node","animation","source_frame","texture","a","b","c","d","tx","ty","offset_x","offset_y","blend","visible","red","green","blue","alpha"]))
	var saved := {}
	stage.spawn_appear(Vector2(150,290))
	for i in range(121):
		capture_tick=i
		if i==9: stage.cast(Vector2(130,150),Vector2(480,190))
		if i==27: stage.cast(Vector2(130,260),Vector2(480,190))
		# Empty-stage marker preserves timing after every effect has been reclaimed.
		f.store_csv_line(PackedStringArray([str(i),str(float(i)/60.0),"","","","","","","","","","","","","","","","","",""]))
		for node in sprites(stage):
			var texture = node.sprite_frames.get_frame_texture(node.animation,node.frame)
			var img = texture.get_image()
			var key = "%s_%03d_%s.png" % [node.animation,node.frame,str(hash(img.get_data()))]
			if not saved.has(key):
				img.save_png(out.path_join("textures").path_join(key))
				saved[key]=true
			var g = node.global_transform
			var color = effective_color(node)
			var offset = node.offset - (Vector2(texture.get_size())/2.0 if node.centered else Vector2.ZERO)
			var blend = node.material.blend_mode if node.material is CanvasItemMaterial else 0
			f.store_csv_line(PackedStringArray([str(i),str(float(i)/60.0),str(node.name),str(node.animation),str(node.frame+(4 if node.animation=="appear" and node.sprite_frames.get_frame_count(node.animation)==45 else 0)),"textures/"+key,str(g.x.x),str(g.y.x),str(g.x.y),str(g.y.y),str(g.origin.x),str(g.origin.y),str(offset.x),str(offset.y),str(blend),str(node.is_visible_in_tree()),str(color.r),str(color.g),str(color.b),str(color.a)]))
		await process_frame
	f.close()
	var ef = FileAccess.open(out.path_join("impact-events.csv"),FileAccess.WRITE)
	ef.store_csv_line(PackedStringArray(["engine_time","x","y"]))
	for event in events:ef.store_csv_line(PackedStringArray(event))
	ef.close()
	print("SAMPLED 121 frames; impacts="+str(events.size()))
	stage.queue_free()
	quit()
